function questionnaireLabel(key){const labels={primary_full_name:"Bride's/Groom's full name",primary_phone:"Bride's/Groom's phone number",primary_email:"Bride's/Groom's email",partner_full_name:"Partner's full name",partner_phone:"Partner's phone number",partner_email:"Partner's email",street_address:"Street address",town:"Town",county:"City / County",postcode:"Postcode",wedding_date:"Wedding date",venue_name:"Wedding venue",venue_address:"Venue address",ceremony_details:"Exact ceremony venue and details",ceremony_time:"Ceremony time",reception_details:"Exact reception venue and details",package_selected:"Package selected",payment_options:"Payment option",wedding_party_size:"Wedding party size",unique_events:"Unique events or details Mark should know",guest_uploads:"Guest photo uploads",additional_information:"Additional information",highlight_music:"Highlight video music choices",timeline:"Full wedding-day timeline",group_photos:"Important family and group photographs",suppliers:"Supplier names and contact details",speeches_time:"Speeches time",first_dance_time:"First dance time",special_requests:"Surprises, sensitivities or special requests",music_suggestions:"Video music suggestions",full_name:"Client name",partner_or_company:"Company",contact_phone:"Contact telephone",address:"Address",service_required:"Project / service required",current_website:"Current website",target_date:"Preferred completion date",additional_notes:"Additional notes"};return labels[key]||statusText(key).replace(/\b\w/g,c=>c.toUpperCase())}
