function renderFinance(r,body){
  const invoiced=r.invoices.reduce((s,i)=>s+i.total,0),paid=r.invoices.reduce((s,i)=>s+i.paid,0);
  const paymentLog=latestEmailLog(state.currentPortal||{},"payment_received");
  const paymentProof=paid>0?`<section class="payment-email-proof"><div><small>LATEST PAYMENT EMAIL</small><strong>${paymentLog?.status==="sent"?"Confirmation sent successfully":paymentLog?.status==="failed"?"Payment recorded · email failed":"No payment-confirmation email recorded"}</strong><span>${paymentLog?.status==="sent"?`${esc(paymentLog.recipient)} · ${esc(fmtDateTime(paymentLog.sent_at))}`:paymentLog?.status==="failed"?esc(paymentLog.error||"Open Quote & emails for the delivery history."):"The payment itself remains safely recorded."}</span></div><i class="${paymentLog?.status||"waiting"}">${paymentLog?.status==="sent"?"✓":paymentLog?.status==="failed"?"!":"○"}</i></section>`:"";
  body.innerHTML=`${paymentProof}<section class="summary"><div><small>QUOTED</small><strong>${money(r.quoted_total)}</strong></div><div><small>INVOICED</small><strong>${money(invoiced)}</strong></div><div><small>PAID</small><strong>${money(paid)}</strong></div></section><div class="section-actions"><div><h3>Invoices & payments</h3><p>View invoices here or download a copy when needed</p></div><button id="new-invoice" class="primary">＋ New invoice</button></div><div class="invoice-cards">${r.invoices.map(i=>`<article class="invoice-card"><header><div><strong>${esc(i.number)}</strong><span class="status ${statusClass(i.status)}">${esc(statusText(i.status))}</span>${i.legacy_number&&i.legacy_number!==i.number?`<small class="legacy-ref">Original reference retained</small>`:""}</div><div class="file-actions"><button class="secondary" data-preview-invoice="${i.id}" data-invoice-number="${attr(i.number)}">View invoice</button><a href="/api/invoices/${i.id}/pdf">Download</a>${i.paid>0?`<a href="/api/invoices/${i.id}/receipt.pdf">Receipt</a>`:""}</div></header><dl><dt>Total</dt><dd>${money(i.total)}</dd><dt>Paid</dt><dd>${money(i.paid)}</dd><dt>Balance</dt><dd><strong>${money(i.balance)}</strong></dd><dt>Final payment due</dt><dd><strong>${i.due_date?esc(fmtDate(i.due_date)):"Not set"}</strong>${i.due_date_overridden?` <span class="agreed-date">Agreed date</span>`:""}</dd></dl>${i.balance>0?`<button class="change-due-date" data-due-invoice="${i.id}" data-due-date="${attr(i.due_date||"")}" data-standard-due="${attr(i.standard_due_date||"")}">Change final payment date</button>`:""}${i.description?`<p>${esc(i.description)}</p>`:""}${i.payment_schedule?.length?`<div class="legacy-schedule"><strong>Payment schedule</strong>${i.payment_schedule.map(item=>`<div><span>${esc(item.label||"Scheduled payment")}<small>${item.due_date?esc(fmtDate(item.due_date)):"No date"} · ${esc(statusText(item.status||"scheduled"))}</small></span><b>${money(item.amount)}</b></div>`).join("")}</div>`:""}<div class="payments">${i.payments.map(p=>`<div data-payment="${p.id}"><span><strong>${money(p.amount)}</strong><small>${esc(fmtDate(p.paid_date))} · ${esc(statusText(p.payment_type))}${p.legacy_source?" · imported":""}</small></span>${p.legacy_source?`<em class="retained-chip">Retained</em>`:`<button class="mini danger-text" data-action="delete-payment">Delete</button>`}</div>`).join("")}</div>${i.balance>0?`<button class="secondary full" data-payment-invoice="${i.id}" data-balance="${i.balance}">Record payment</button>`:""}</article>`).join("")||`<div class="empty small-empty"><strong>No invoices yet</strong>Create the first branded invoice above.</div>`}</div>`;
  $("#new-invoice").onclick=()=>newInvoice(r);
  $$('[data-preview-invoice]',body).forEach(button=>button.onclick=()=>showPdfPreview(`Invoice ${button.dataset.invoiceNumber}`,`/api/invoices/${button.dataset.previewInvoice}/pdf?inline=true`,`/api/invoices/${button.dataset.previewInvoice}/pdf`));
  $$('[data-payment-invoice]',body).forEach(b=>b.onclick=()=>recordPayment(r,b.dataset.paymentInvoice,Number(b.dataset.balance)));
  $$('[data-due-invoice]',body).forEach(b=>b.onclick=()=>changeInvoiceDueDate(r,b.dataset.dueInvoice,b.dataset.dueDate,b.dataset.standardDue));
  $$('[data-action="delete-payment"]',body).forEach(b=>b.onclick=async()=>{if(!confirm("Remove this payment entry?"))return;await api(`/api/payments/${b.closest("[data-payment]").dataset.payment}`,{method:"DELETE"});toast("Payment removed");openDrawer(r.id,"Finance")});
}
function changeInvoiceDueDate(r,invoiceId,currentDue,standardDue){
  const help=standardDue?`The usual 45-day date is ${fmtDate(standardDue)}. Changing this affects only this couple and reschedules their payment reminders.`:`This changes only this invoice and its payment reminders.`;
  showModal("Change final payment date",`<label class="full">New agreed payment date<input id="agreed-due-date" type="date" value="${attr(currentDue||standardDue||"")}" required></label><label class="full">Private reason (optional)<textarea id="agreed-due-reason" rows="3" placeholder="For example: extension agreed with the couple"></textarea></label>`,async()=>{const updated=await api(`/api/invoices/${invoiceId}/due-date`,{method:"PATCH",body:JSON.stringify({due_date:value("#agreed-due-date"),reason:nullable(value("#agreed-due-reason"))})});closeModal();await refresh();toast(`Final payment date changed to ${fmtDate(updated.due_date)}`);openDrawer(r.id,"Payments")},help)
}
function newInvoice(r){showModal("Create branded invoice",`<label>Total<input id="invoice-total" type="number" min="0.01" step="0.01" value="${Number(r.quoted_total||0)}" required></label><label>Already paid<input id="invoice-paid" type="number" min="0" step="0.01" value="${Number(r.deposit_amount||0)}"></label><label>Issue date<input id="invoice-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Due date<input id="invoice-due" type="date" value="${attr(r.balance_due_date||"")}"></label><label class="full">Description<textarea id="invoice-description" rows="3">${esc(r.package_name||r.venue_or_project||"")}</textarea></label><label class="full">Invoice notes<textarea id="invoice-notes" rows="2" placeholder="Optional"></textarea></label>`,async()=>{const i=await api(`/api/bookings/${r.id}/invoices`,{method:"POST",body:JSON.stringify({total:Number(value("#invoice-total")),paid:Number(value("#invoice-paid")||0),issue_date:value("#invoice-date"),due_date:nullable(value("#invoice-due")),supply_date:r.event_date,description:nullable(value("#invoice-description")),notes:nullable(value("#invoice-notes"))})});closeModal();await refresh();toast(`Invoice ${i.number} created`);openDrawer(r.id,"Finance")},`The next number will use the independent ${r.brand==="wbm"?"WBM":"ID"} counter.`)}
function recordPayment(r,invoiceId,balance){showModal("Record payment",`<label>Amount<input id="payment-amount" type="number" min="0.01" max="${balance}" step="0.01" value="${balance}" required></label><label>Date received<input id="payment-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Payment method<select id="payment-method" required><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option></select></label><label>Reference<input id="payment-reference" placeholder="Invoice number or reference"></label><label class="full">Notes<textarea id="payment-notes" rows="2" placeholder="Optional private note"></textarea></label>`,async()=>{const method=value("#payment-method");const result=await api(`/api/invoices/${invoiceId}/payments`,{method:"POST",body:JSON.stringify({amount:Number(value("#payment-amount")),paid_date:value("#payment-date"),payment_type:method,reference:nullable(value("#payment-reference")),notes:nullable(value("#payment-notes"))})});closeModal();await refresh();const label=statusText(method);if(result.payment_email_sent)toast(`${label} recorded and confirmation emailed`);else if(result.payment_email_paused)toast(`${label} recorded; client email remains safely paused`);else if(result.payment_email_error)toast(`Payment recorded, but the email was not sent: ${result.payment_email_error}`,"error");else toast(`${label} recorded`);openDrawer(r.id,"Finance")},"Choose Cash when money was handed to you in person. It will sync to Accounts as genuine cash income without requiring a bank transaction.")}
async function toggleArchive(r){const action=r.archived?"restore":"archive";if(!r.archived&&!confirm("Archive this record? You can restore it from the Archived filter."))return;try{await api(`/api/bookings/${r.id}/${action}`,{method:"POST"});closeDrawer();await refresh();toast(r.archived?"Record restored":"Record archived");render()}catch(e){toast(e.message,"error")}}
function showError(e){$("#content").innerHTML=`<div class="panel empty"><strong>Something went wrong</strong>${esc(e.message)}</div>`}

init();
